 return head('Daily Ingest Dossier — '+g['title'])+f'''<header><div class="wordmark">{logo()}<span>Buildn</span></div><h1>Daily Ingest Dossier — {e(g['title'])}</h1><div class="badges"><span class="badge">{DATE}</span><span class="badge good">adaptive coverage</span></div><p class="deck">{e(g['selection_rationale'])} Three primary-source signals; each earns attention because it can become a bounded operating experiment.</p></header><section><article class="card"><h2>Signal map</h2>{signal(g)}<p><span class="hl">Editorial read:</span> capability is cheap; admissibility, isolation, and evidence are the compounding advantages.</p></article>{cards}<article class="card"><h2>Use-case matrix</h2><table class="matrix"><tr><th>Signal</th><th>Buildn OS</th><th>Client work</th><th>Agent workflows</th><th>Personal leverage</th></tr>{rows}</table></article><article class="card top"><h2>Top actions</h2><ol>{''.join(f'<li><a href="#item-{i}">{e(s["action"])}</a></li>' for i,s in enumerate(g['sources'],1))}</ol></article><article class="card"><h2>Source trail</h2><ul>{trail}</ul></article></section><footer>Daily Ingest • {DATE} • Direct primary sources</footer></main></body></html>'''

